  const snapIndex = (time) => Math.min(run.snapTimes.length - 1, Math.max(0, Math.round((time - run.snapTimes[0]) / (run.snapTimes[1] - run.snapTimes[0]))));
  const t0 = state.disturbances ? regime.t0 : 0;
