  series.push({ x: xs, y: Array.from(run.snaps[snapIndex(t)]), color: caseColor, width: 2.4 });
  series.push({ x: xs, y: Array.from(loop.Tstar), color: p.tstar, width: 1.4, dash: [5, 4] });
