  const fills = Math.abs(env) > 0.05 ? [{ x: xs, lo: xs.map(() => 0), hi: xs.map((_, i) => env * loop.shape[i]), color: alpha(env > 0 ? p.hot : p.cold, 0.35) }] : [];
